#!/usr/bin/env node
/**
 * Generates workers/src/instructions.ts from:
 *   - agents/rescue-bot-instruction.md  (generic instruction with {{SITE_INSTRUCTION}} placeholder)
 *   - site/agent-instruction.md          (org-specific instruction)
 *
 * Run: node workers/scripts/gen-instructions.js
 *
 * The generated file is imported by the Worker at bundle time — no runtime
 * secrets needed for the instruction text. It is gitignored (org-specific).
 */

import { readFileSync, writeFileSync, existsSync } from 'fs'
import { join, dirname } from 'path'
import { fileURLToPath } from 'url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const root = join(__dirname, '../..')

// ── 1. Read generic instruction ─────────────────────────────────────────────
const genericInstruction = readFileSync(join(root, 'agents/rescue-bot-instruction.md'), 'utf8')

// ── 2. Read site instruction ──────────────────────────────────────────────────
let siteInstruction = ''
const siteInstructionPath = join(root, 'site/agent-instruction.md')
if (existsSync(siteInstructionPath)) {
  siteInstruction = readFileSync(siteInstructionPath, 'utf8')
} else {
  console.warn('WARN: site/agent-instruction.md not found — SITE_INSTRUCTION will be empty')
}

// HTML comments in these markdown files are dev-facing documentation — they
// must NOT ship in the LLM prompt (they burn context on every request and
// show up as noise in the admin "what your bot sees" view). Strip them.
const stripHtmlComments = (s) => s.replace(/<!--[\s\S]*?-->/g, '')
siteInstruction = stripHtmlComments(siteInstruction).trim()

// ── 3. Combine ────────────────────────────────────────────────────────────────
let combinedInstruction
if (siteInstruction) {
  combinedInstruction = genericInstruction.replace('{{SITE_INSTRUCTION}}', siteInstruction)
} else {
  // No deployment-wide site instruction → don't ship an empty
  // "## ORGANIZATION-SPECIFIC INSTRUCTIONS" heading with nothing under it.
  combinedInstruction = genericInstruction
    .replace(/\n*##+ ORGANIZATION-SPECIFIC INSTRUCTIONS\s*\n+\{\{SITE_INSTRUCTION\}\}/g, '')
    .replace('{{SITE_INSTRUCTION}}', '')
}
combinedInstruction = stripHtmlComments(combinedInstruction).trim()

// ── 4. Write TypeScript module ────────────────────────────────────────────────
const ts = `// AUTO-GENERATED by workers/scripts/gen-instructions.js — do not edit
// Re-run: node workers/scripts/gen-instructions.js
// Regenerate before each deploy: make cf-deploy will do this automatically.

export const COMBINED_INSTRUCTION = ${JSON.stringify(combinedInstruction)}
`

const outPath = join(__dirname, '../src/instructions.ts')
writeFileSync(outPath, ts)
console.log('✓ Generated workers/src/instructions.ts')
console.log(`  Combined instruction: ${combinedInstruction.split('\n').length} lines, ${combinedInstruction.length} chars`)
